#!/usr/bin/env node

/**
 * @ai-generated by aurorayang
 * @date 2026-03-05
 * AI 代码统计脚本
 * 在 commit 前统计暂存区代码的 AI 生成比例，并生成个人报告
 */

const { execSync } = require('child_process');
const fs = require('fs');
const path = require('path');

// 颜色输出
const colors = {
  reset: '\x1b[0m',
  bright: '\x1b[1m',
  red: '\x1b[31m',
  green: '\x1b[32m',
  yellow: '\x1b[33m',
  blue: '\x1b[34m',
  cyan: '\x1b[36m',
};

function log(message, color = 'reset') {
  console.log(`${colors[color]}${message}${colors.reset}`);
}

// 执行 git 命令
function execGit(command) {
  try {
    return execSync(command, { encoding: 'utf-8', cwd: process.cwd() }).trim();
  } catch (error) {
    return '';
  }
}

// 获取当前 Git 用户名
function getGitUserName() {
  const username = execGit('git config user.name');
  return username || 'unknown';
}

// 获取命令行参数中的需求名（第一个参数）
function getCommandLineTaskName() {
  const args = process.argv.slice(2);
  if (args.length > 0 && args[0]) {
    return args[0];
  }
  return null;
}

// 获取命令行参数中的用户名（第二个参数）
function getCommandLineUserName() {
  const args = process.argv.slice(2);
  if (args.length > 1 && args[1]) {
    return args[1];
  }
  return null;
}

// 获取即将提交的 commit 信息（用于默认需求名）
function getCommitMessage() {
  // 尝试从 git commit 命令中获取提交信息
  // 优先使用暂存区的 commit message（如果有）
  const message = execGit('git log -1 --pretty=format:%s HEAD');
  return message || '未命名任务';
}

// 获取最新 commit 的变更统计
function getCommitStats() {
  const output = execGit('git show --numstat --format= HEAD');
  if (!output) return { files: [], totalAdd: 0, totalDel: 0 };

  const lines = output.split('\n').filter((line) => line.trim());
  const files = [];
  let totalAdd = 0;
  let totalDel = 0;

  lines.forEach((line) => {
    const parts = line.split('\t');
    if (parts.length >= 3) {
      const add = parseInt(parts[0], 10) || 0;
      const del = parseInt(parts[1], 10) || 0;
      const filePath = parts[2];

      // 排除特定路径（包括 AI-Generate 目录，避免自引用）
      if (!shouldExclude(filePath) && !shouldExcludeAIGenerate(filePath)) {
        files.push({ path: filePath, add, del });
        totalAdd += add;
        totalDel += del;
      }
    }
  });

  return { files, totalAdd, totalDel };
}

// 获取文件变更内容（从最新 commit）
function getFileDiff(filePath) {
  return execGit(`git show HEAD -- "${filePath}"`);
}

// 排除特定路径
function shouldExclude(filePath) {
  // 注意：AI-Generate/ 目录下的文件需要提交到 git，但在统计时要排除
  // 避免自引用（统计自身生成的报告）
  const excludePatterns = ['node_modules/', 'dist/', 'build/', '.git/', '.lingma/'];
  return excludePatterns.some((pattern) => filePath.includes(pattern));
}

// 排除 AI-Generate 目录（用于暂存区统计）
function shouldExcludeAIGenerate(filePath) {
  // 移除可能的引号（git diff 输出有时会包裹路径）
  const cleanPath = filePath.replace(/^["']|["']$/g, '');
  return cleanPath.includes('AI-Generate/') || cleanPath.includes('AI-Generate\\');
}

// 检查文件是否为 AI 生成（完整文件）
function isAIGeneratedFile(filePath) {
  try {
    const content = fs.readFileSync(filePath, 'utf-8');
    const lines = content.split('\n');
    // 检查前 20 行是否包含 @ai-generated 标记
    const header = lines.slice(0, 20).join('\n');
    return header.includes('@ai-generated') && header.includes('@date');
  } catch (error) {
    return false;
  }
}

// 分析文件中的 AI 生成代码段
function analyzeAIGeneratedSections(filePath) {
  const diff = getFileDiff(filePath);
  if (!diff) return { aiLines: 0, sections: [] };

  const lines = diff.split('\n');
  let aiLines = 0;
  let inAIGeneratedBlock = false;
  const sections = [];
  let currentSection = null;

  lines.forEach((line, index) => {
    // 只统计新增的行（以 + 开头，但不是 +++）
    if (line.startsWith('+') && !line.startsWith('+++')) {
      const content = line.substring(1);

      // 检测 AI 生成开始标记
      if (content.includes('@ai-generated-start')) {
        inAIGeneratedBlock = true;
        currentSection = { startLine: index, lines: 0 };
      }

      // 检测 AI 生成结束标记
      if (content.includes('@ai-generated-end')) {
        if (currentSection) {
          sections.push(currentSection);
        }
        inAIGeneratedBlock = false;
        currentSection = null;
      }

      // 统计 AI 生成行数
      if (inAIGeneratedBlock) {
        aiLines++;
        if (currentSection) {
          currentSection.lines++;
        }
      }
    }
  });

  return { aiLines, sections };
}

// 获取文件类型
function getFileType(filePath) {
  const ext = path.extname(filePath).toLowerCase();
  const typeMap = {
    '.ts': 'TypeScript',
    '.tsx': 'TypeScript React',
    '.js': 'JavaScript',
    '.jsx': 'JavaScript React',
    '.mpx': 'MPX',
    '.vue': 'Vue',
    '.less': 'Less',
    '.scss': 'Scss',
    '.css': 'CSS',
    '.json': 'JSON',
    '.md': 'Markdown',
  };
  return typeMap[ext] || 'Other';
}

// 获取提交信息
function getCommitInfo() {
  const hash = execGit('git rev-parse --short HEAD');
  const message = execGit('git log -1 --pretty=format:%s HEAD');
  return { hash, message };
}

// 获取暂存区的 tree hash（作为暂存区内容的唯一标识）
function getStagedTreeHash() {
  // 使用 git write-tree 获取暂存区的 tree hash（更可靠）
  const treeHash = execGit('git write-tree');
  if (treeHash) {
    return treeHash;
  }
  // 降级方案：使用文件列表的 hash
  return execGit('git diff --cached --name-only | sort | md5sum | cut -d" " -f1');
}

// 检查是否已经为当前暂存区生成过报告
function checkExistingReport(username, projectRoot, commitHash) {
  const userDir = path.join(projectRoot, 'AI-Generate', username);
  if (!fs.existsSync(userDir)) {
    return null;
  }

  // 读取所有报告文件
  const reportFiles = fs.readdirSync(userDir).filter((f) => f.startsWith('ai-code-report-') && f.endsWith('.md'));

  for (const reportFile of reportFiles) {
    const reportPath = path.join(userDir, reportFile);
    try {
      const content = fs.readFileSync(reportPath, 'utf-8');
      // 使用正则表达式匹配 commit-hash（处理可能的换行）
      const hashMatch = content.match(/\*\*commit-hash\*\*:\s*([a-f0-9]+)/);
      if (hashMatch && hashMatch[1] === commitHash) {
        return reportPath;
      }
    } catch (error) {
      // 忽略读取错误
    }
  }

  return null;
}

// 读取 summary.md 中的累计数据
function readSummaryStats(username, projectRoot) {
  const summaryPath = path.join(projectRoot, 'AI-Generate', username, 'summary.md');
  if (!fs.existsSync(summaryPath)) {
    return { totalFiles: 0, totalAdd: 0, totalDel: 0, totalAIFiles: 0, totalAILines: 0 };
  }

  try {
    const content = fs.readFileSync(summaryPath, 'utf-8');
    const filesMatch = content.match(/累计变更文件总数\s*\|\s*(\d+)/);
    const addMatch = content.match(/累计新增代码行数\s*\|\s*(\d+)/);
    const delMatch = content.match(/累计删除代码行数\s*\|\s*(\d+)/);
    const aiFilesMatch = content.match(/累计 AI 生成文件数\s*\|\s*(\d+)/);
    const aiLinesMatch = content.match(/累计 AI 生成代码行数\s*\|\s*(\d+)/);

    return {
      totalFiles: parseInt(filesMatch?.[1], 10) || 0,
      totalAdd: parseInt(addMatch?.[1], 10) || 0,
      totalDel: parseInt(delMatch?.[1], 10) || 0,
      totalAIFiles: parseInt(aiFilesMatch?.[1], 10) || 0,
      totalAILines: parseInt(aiLinesMatch?.[1], 10) || 0,
    };
  } catch (error) {
    return { totalFiles: 0, totalAdd: 0, totalDel: 0, totalAIFiles: 0, totalAILines: 0 };
  }
}

// 更新历史累计统计（累加模式）
function updateHistoricalStats(username, projectRoot, currentStats, isUpdate = false) {
  const userDir = path.join(projectRoot, 'AI-Generate', username);
  const summaryPath = path.join(userDir, 'summary.md');

  // 读取已有累计数据
  const history = readSummaryStats(username, projectRoot);

  // 如果是更新模式，需要先减去旧数据（这里简化处理，直接累加）
  // 实际场景中，更新报告时应该减去该报告之前的数据
  const newStats = {
    totalFiles: history.totalFiles + (isUpdate ? 0 : currentStats.totalFiles),
    totalAdd: history.totalAdd + (isUpdate ? 0 : currentStats.totalAdd),
    totalDel: history.totalDel + (isUpdate ? 0 : currentStats.totalDel),
    totalAIFiles: history.totalAIFiles + (isUpdate ? 0 : (currentStats.aiFiles?.length || 0)),
    totalAILines: history.totalAILines + (isUpdate ? 0 : currentStats.totalAILines),
  };

  // 计算平均占比
  const aiPercent = newStats.totalAdd > 0 ? ((newStats.totalAILines / newStats.totalAdd) * 100).toFixed(1) : '0.0';

  const summaryContent = `# AI 代码生成累计统计

**用户**: ${username}
**最后更新**: ${new Date().toLocaleString('zh-CN')}

---

## 累计统计摘要

| 指标 | 数值 |
|------|------|
| 累计变更文件总数 | ${newStats.totalFiles} |
| 累计新增代码行数 | ${newStats.totalAdd} |
| 累计删除代码行数 | ${newStats.totalDel} |
| 累计净变更行数 | ${newStats.totalAdd - newStats.totalDel} |
| 累计 AI 生成文件数 | ${newStats.totalAIFiles} |
| 累计 AI 生成代码行数 | ${newStats.totalAILines} |
| **累计 AI 代码占比** | **${aiPercent}%** |

---

*自动更新于每次 AI 代码统计*
`;

  fs.writeFileSync(summaryPath, summaryContent, 'utf-8');

  return newStats;
}

// 查找指定需求名的报告
function findReportByTaskName(username, projectRoot, taskName) {
  if (!taskName) return null;

  const userDir = path.join(projectRoot, 'AI-Generate', username);
  if (!fs.existsSync(userDir)) {
    return null;
  }

  // 规范化需求名（用于文件名）
  const normalizedTaskName = taskName.replace(/[^a-zA-Z0-9\u4e00-\u9fa5_-]/g, '_');

  // 查找匹配的报告文件
  const reportFiles = fs.readdirSync(userDir).filter((f) => f.includes(normalizedTaskName) && f.endsWith('.md'));

  if (reportFiles.length > 0) {
    // 返回最新的匹配报告
    const sortedFiles = reportFiles
      .map((f) => ({ name: f, path: path.join(userDir, f), stat: fs.statSync(path.join(userDir, f)) }))
      .sort((a, b) => b.stat.mtime - a.stat.mtime);
    return sortedFiles[0].path;
  }

  return null;
}

// 追加文件清单到现有报告
function appendFileListsToReport(existingContent, newStats, newReportContent) {
  const now = new Date().toLocaleString('zh-CN');

  // 生成新的 AI 文件清单
  const newAIFilesList = newStats.aiFiles
    .map((file) => {
      return `| \`${file.path}\` | ${file.type} | ${file.aiLines} | ${file.isFullAIGenerated ? '完整文件' : '部分代码'} |`;
    })
    .join('\n');

  // 生成新的人工编写文件清单
  const newManualFilesList = newStats.manualFiles
    .map((file) => {
      return `| \`${file.path}\` | ${file.type} | +${file.add}/-${file.del} |`;
    })
    .join('\n');

  // 在报告末尾追加新的变更记录
  const appendSection = `

---

## 变更记录 ${now}

### 本次 AI 生成文件

| 文件路径 | 类型 | AI 生成行数 | 标记类型 |
|----------|------|-------------|----------|
${newAIFilesList || '| 无 | - | - | - |'}

### 本次人工编写文件

| 文件路径 | 类型 | 变更行数 |
|----------|------|----------|
${newManualFilesList || '| 无 | - | - |'}

### 本次文件详细统计

${newStats.allFiles
  .map(
    (file) => `
#### ${file.path}
- 文件类型: ${file.type}
- 新增行数: ${file.add}
- 删除行数: ${file.del}
- AI 生成行数: ${file.aiLines}
- AI 占比: ${file.add > 0 ? ((file.aiLines / file.add) * 100).toFixed(1) : 0}%
- 是否完整 AI 生成: ${file.isFullAIGenerated ? '是' : '否'}
`,
  )
  .join('')}
`;

  // 替换统计摘要部分，保留文件清单历史
  let updatedContent = existingContent.replace(
    /## 统计摘要[\s\S]*?(?=## AI 生成文件清单|$)/,
    newReportContent.match(/## 统计摘要[\s\S]*?(?=## AI 生成文件清单|$)/)?.[0] || ''
  );

  // 更新 staged-hash 为最新的（用于防重复统计）
  const newStagedHash = newReportContent.match(/\*\*staged-hash\*\*:\s*([a-f0-9]+)/)?.[1];
  if (newStagedHash) {
    updatedContent = updatedContent.replace(/\*\*staged-hash\*\*:\s*[a-f0-9]+/, `**commit-hash**: ${newStagedHash}`);
  }

  // 更新提交哈希和信息
  const newCommitHash = newReportContent.match(/\*\*提交哈希\*\*:\s*([a-f0-9]+)/)?.[1];
  const newCommitMsg = newReportContent.match(/\*\*提交信息\*\*:\s*([^\n]+)/)?.[1];
  if (newCommitHash) {
    updatedContent = updatedContent.replace(/\*\*提交哈希\*\*:\s*[a-f0-9]+/, `**提交哈希**: ${newCommitHash}`);
  }
  if (newCommitMsg) {
    updatedContent = updatedContent.replace(/\*\*提交信息\*\*:\s*[^\n]+/, `**提交信息**: ${newCommitMsg}`);
  }

  return updatedContent + appendSection;
}

// 从现有报告中提取累计数据
function extractExistingStats(existingContent) {
  try {
    const totalFilesMatch = existingContent.match(/变更文件总数\s*\|\s*(\d+)/);
    const totalAddMatch = existingContent.match(/新增代码行数\s*\|\s*(\d+)/);
    const totalDelMatch = existingContent.match(/删除代码行数\s*\|\s*(\d+)/);
    const aiFilesMatch = existingContent.match(/AI 生成文件数\s*\|\s*(\d+)/);
    const aiLinesMatch = existingContent.match(/AI 生成代码行数\s*\|\s*(\d+)/);

    return {
      totalFiles: parseInt(totalFilesMatch?.[1], 10) || 0,
      totalAdd: parseInt(totalAddMatch?.[1], 10) || 0,
      totalDel: parseInt(totalDelMatch?.[1], 10) || 0,
      aiFiles: parseInt(aiFilesMatch?.[1], 10) || 0,
      aiLines: parseInt(aiLinesMatch?.[1], 10) || 0,
    };
  } catch (error) {
    return { totalFiles: 0, totalAdd: 0, totalDel: 0, aiFiles: 0, aiLines: 0 };
  }
}

// 获取文件的 git blob hash
function getFileBlobHash(filePath) {
  try {
    return execGit(`git hash-object "${filePath}"`);
  } catch (error) {
    return null;
  }
}

// 从所有历史报告中提取已统计的文件及其 hash
function getAllReportedFilesWithHash(username, projectRoot) {
  const userDir = path.join(projectRoot, 'AI-Generate', username);
  if (!fs.existsSync(userDir)) {
    return new Map();
  }

  const reportedFiles = new Map(); // path -> hash
  const reportFiles = fs.readdirSync(userDir).filter((f) => f.startsWith('ai-code-report-') && f.endsWith('.md'));

  for (const reportFile of reportFiles) {
    const reportPath = path.join(userDir, reportFile);
    try {
      const content = fs.readFileSync(reportPath, 'utf-8');
      // 匹配文件详细统计中的文件路径和 hash
      const fileMatches = content.matchAll(/###\s+([^\n]+)\n[\s\S]*?-\s*文件\s*hash:\s*([a-f0-9]+)/g);
      for (const match of fileMatches) {
        const filePath = match[1].trim();
        const fileHash = match[2].trim();
        // 只保留最新的 hash（后面的报告会覆盖前面的）
        reportedFiles.set(filePath, fileHash);
      }
    } catch (error) {
      // 忽略读取错误
    }
  }

  return reportedFiles;
}

// 生成报告内容
function generateReportContent(username, stats, commitInfo, stagedHash, taskName, isUpdate = false, existingContent = null) {
  const now = new Date().toLocaleString('zh-CN');

  // 如果是更新模式，合并历史数据
  let mergedStats = {
    totalFiles: stats.totalFiles,
    totalAdd: stats.totalAdd,
    totalDel: stats.totalDel,
    aiFiles: stats.aiFiles?.length || 0,
    totalAILines: stats.totalAILines,
  };
  if (isUpdate && existingContent) {
    const existing = extractExistingStats(existingContent);
    mergedStats = {
      totalFiles: existing.totalFiles + stats.totalFiles,
      totalAdd: existing.totalAdd + stats.totalAdd,
      totalDel: existing.totalDel + stats.totalDel,
      aiFiles: existing.aiFiles + (stats.aiFiles?.length || 0),
      totalAILines: existing.aiLines + stats.totalAILines,
    };
  }

  // 重新计算 AI 代码占比
  const aiLinePercent = mergedStats.totalAdd > 0 ? ((mergedStats.totalAILines / mergedStats.totalAdd) * 100).toFixed(1) : '0.0';

  // 生成 AI 文件清单（累加本次的）
  const aiFilesList = stats.aiFiles
    .map((file, index) => {
      return `| ${index + 1} | \`${file.path}\` | ${file.type} | ${file.aiLines} | ${file.isFullAIGenerated ? '完整文件' : '部分代码'} |`;
    })
    .join('\n');

  // 生成修改文件清单（非 AI 生成）
  const manualFilesList = stats.manualFiles
    .map((file, index) => {
      return `| ${index + 1} | \`${file.path}\` | ${file.type} | +${file.add}/-${file.del} |`;
    })
    .join('\n');

  const updateInfo = isUpdate ? `
**更新时间**: ${now}
**更新次数**: +1` : '';

  return `# AI 代码生成统计报告${taskName ? ` - ${taskName}` : ''}

**生成时间**: ${now}${updateInfo}
**统计人**: ${username}
**提交哈希**: ${commitInfo.hash || 'N/A'}
**提交信息**: ${commitInfo.message || 'N/A'}
**commit-hash**: ${stagedHash}

---

## 统计摘要

| 指标 | 数值 |
|------|------|
| 变更文件总数 | ${mergedStats.totalFiles} |
| 新增代码行数 | ${mergedStats.totalAdd} |
| 删除代码行数 | ${mergedStats.totalDel} |
| 净变更行数 | ${mergedStats.totalAdd - mergedStats.totalDel} |
| AI 生成文件数 | ${mergedStats.aiFiles} |
| AI 生成代码行数 | ${mergedStats.totalAILines} |
| **AI 代码占比** | **${aiLinePercent}%** |

---

## AI 生成文件清单

| 序号 | 文件路径 | 类型 | AI 生成行数 | 标记类型 |
|------|----------|------|-------------|----------|
${aiFilesList || '| - | 无 | - | - | - |'}

---

## 人工编写文件清单

| 序号 | 文件路径 | 类型 | 变更行数 |
|------|----------|------|----------|
${manualFilesList || '| - | 无 | - | - |'}

---

## 文件详细统计

${stats.allFiles
  .map(
    (file) => {
      const fileHash = getFileBlobHash(file.path);
      return `
### ${file.path}
- 文件类型: ${file.type}
- 文件 hash: ${fileHash || 'N/A'}
- 新增行数: ${file.add}
- 删除行数: ${file.del}
- AI 生成行数: ${file.aiLines}
- AI 占比: ${file.add > 0 ? ((file.aiLines / file.add) * 100).toFixed(1) : 0}%
- 是否完整 AI 生成: ${file.isFullAIGenerated ? '是' : '否'}
`;
    }
  )
  .join('')}

---

*报告由 AI Code Stats Skill 自动生成*
`;
}

// 生成或更新报告
function generateReport(username, stats, commitInfo, projectRoot, stagedHash, taskName) {
  const userDir = path.join(projectRoot, 'AI-Generate', username);

  // 创建目录
  if (!fs.existsSync(userDir)) {
    fs.mkdirSync(userDir, { recursive: true });
  }

  // 检查是否已存在相同需求名的报告
  const existingReport = taskName ? findReportByTaskName(username, projectRoot, taskName) : null;

  let reportPath;
  let isUpdate = false;

  if (existingReport) {
    // 更新现有报告
    reportPath = existingReport;
    isUpdate = true;
  } else {
    // 生成新报告
    const date = new Date().toISOString().slice(0, 10);
    const normalizedTaskName = taskName ? taskName.replace(/[^a-zA-Z0-9\u4e00-\u9fa5_-]/g, '_') : '';
    const filename = normalizedTaskName
      ? `ai-code-report-${date}-${normalizedTaskName}.md`
      : `ai-code-report-${new Date().toISOString().replace(/[:.]/g, '-').slice(0, 19)}.md`;
    reportPath = path.join(userDir, filename);
  }

  // 读取现有报告内容（如果是更新模式）
  let existingContent = null;
  if (isUpdate && fs.existsSync(reportPath)) {
    existingContent = fs.readFileSync(reportPath, 'utf-8');
  }

  // 生成报告内容（合并历史数据）
  const reportContent = generateReportContent(username, stats, commitInfo, stagedHash, taskName, isUpdate, existingContent);

  // 如果是更新模式，追加新的文件清单到现有报告
  if (isUpdate && existingContent) {
    const appendedContent = appendFileListsToReport(existingContent, stats, reportContent);
    fs.writeFileSync(reportPath, appendedContent, 'utf-8');
  } else {
    fs.writeFileSync(reportPath, reportContent, 'utf-8');
  }

  return { reportPath, isUpdate };
}

// 主函数
function main() {
  log('🔍 AI 代码统计', 'bright');
  log('================', 'bright');

  // 检查是否在 git 仓库中
  const gitDir = execGit('git rev-parse --git-dir');
  if (!gitDir) {
    log('❌ 错误: 当前目录不是 Git 仓库', 'red');
    process.exit(1);
  }

  // 获取用户名（优先使用命令行参数，否则使用 Git 用户名）
  const cliUsername = getCommandLineUserName();
  const gitUsername = getGitUserName();
  const username = cliUsername || gitUsername;

  // 获取需求名（优先使用命令行参数，否则使用 commit message）
  const cliTaskName = getCommandLineTaskName();
  const commitMessage = getCommitMessage();
  const taskName = cliTaskName || commitMessage;

  if (cliUsername) {
    log(`统计人: ${username} (命令行指定)`, 'cyan');
    log(`Git 用户: ${gitUsername}`, 'blue');
  } else {
    log(`统计人: ${username} (Git 用户名)`, 'cyan');
  }

  if (cliTaskName) {
    log(`需求名称: ${taskName} (命令行指定)`, 'cyan');
  } else {
    log(`需求名称: ${taskName} (自动获取)`, 'cyan');
  }

  // 获取最新 commit 统计
  const commitStats = getCommitStats();
  if (commitStats.files.length === 0) {
    log('⚠️ 最新 commit 没有变更文件，无需统计', 'yellow');
    process.exit(0);
  }

  log(`变更文件: ${commitStats.files.length} 个`, 'blue');
  log(`新增行数: ${commitStats.totalAdd}`, 'green');
  log(`删除行数: ${commitStats.totalDel}`, 'red');

  // 分析每个文件
  const allFiles = [];
  const aiFiles = [];
  const manualFiles = [];
  let totalAILines = 0;

  commitStats.files.forEach((file) => {
    const filePath = path.join(process.cwd(), file.path);
    const type = getFileType(file.path);

    // 检查是否为完整 AI 生成文件
    const isFullAIGenerated = fs.existsSync(filePath) && isAIGeneratedFile(filePath);

    // 分析 AI 生成代码段
    const aiAnalysis = analyzeAIGeneratedSections(file.path);

    // 如果是完整 AI 生成文件，所有新增行都算作 AI 生成
    const aiLines = isFullAIGenerated ? file.add : aiAnalysis.aiLines;

    const fileStat = {
      path: file.path,
      type,
      add: file.add,
      del: file.del,
      aiLines,
      isFullAIGenerated,
    };

    allFiles.push(fileStat);

    if (aiLines > 0 || isFullAIGenerated) {
      aiFiles.push(fileStat);
      totalAILines += aiLines;
    } else {
      manualFiles.push(fileStat);
    }
  });

  log('\n🤖 AI 生成统计', 'bright');
  log('================', 'bright');
  log(`AI 生成文件: ${aiFiles.length} 个`, 'cyan');
  log(`AI 生成行数: ${totalAILines} 行`, 'cyan');

  const aiPercent = commitStats.totalAdd > 0 ? ((totalAILines / commitStats.totalAdd) * 100).toFixed(1) : '0.0';
  log(`AI 代码占比: ${aiPercent}%`, aiPercent > 50 ? 'yellow' : 'green');

  // 获取提交信息
  const commitInfo = getCommitInfo();

  // 获取当前 commit hash，用于防重复统计
  const commitHash = execGit('git rev-parse HEAD');

  // 检查是否已统计过这个 commit
  const existingReportByCommit = checkExistingReport(username, process.cwd(), commitHash);
  if (existingReportByCommit) {
    log('\n📄 检测到已有报告', 'bright');
    log('================', 'bright');
    log(`路径: ${existingReportByCommit}`, 'green');
    log('提示: 当前 commit 已统计过，跳过重复统计', 'yellow');
    return;
  }

  // 获取已统计的文件及其 hash
  const reportedFilesWithHash = getAllReportedFilesWithHash(username, process.cwd());

  // 过滤未变化的文件（hash 相同的文件）
  const newAIFiles = aiFiles.filter((file) => {
    const currentHash = getFileBlobHash(file.path);
    const reportedHash = reportedFilesWithHash.get(file.path);
    // 如果 hash 不同或文件未统计过，则保留
    return !reportedHash || reportedHash !== currentHash;
  });
  const newManualFiles = manualFiles.filter((file) => {
    const currentHash = getFileBlobHash(file.path);
    const reportedHash = reportedFilesWithHash.get(file.path);
    return !reportedHash || reportedHash !== currentHash;
  });
  const newAllFiles = allFiles.filter((file) => {
    const currentHash = getFileBlobHash(file.path);
    const reportedHash = reportedFilesWithHash.get(file.path);
    return !reportedHash || reportedHash !== currentHash;
  });

  // 重新计算统计数据（只统计变化的文件）
  const newTotalAdd = newAllFiles.reduce((sum, file) => sum + file.add, 0);
  const newTotalDel = newAllFiles.reduce((sum, file) => sum + file.del, 0);
  const newTotalAILines = newAIFiles.reduce((sum, file) => sum + file.aiLines, 0);

  // 显示过滤信息
  const filteredCount = commitStats.files.length - newAllFiles.length;
  if (filteredCount > 0) {
    log(`\n📝 已过滤 ${filteredCount} 个未变化的文件（内容未修改）`, 'blue');
  }

  // 准备统计数据
  const stats = {
    totalFiles: newAllFiles.length,
    totalAdd: newTotalAdd,
    totalDel: newTotalDel,
    totalAILines: newTotalAILines,
    aiFiles: newAIFiles,
    manualFiles: newManualFiles,
    allFiles: newAllFiles,
  };

  // 检查是否已存在相同 stagedHash 的报告（完全相同的暂存区内容）
  const existingReportByHash = checkExistingReport(username, process.cwd(), commitHash);
  if (existingReportByHash) {
    log('\n📄 检测到已有报告', 'bright');
    log('================', 'bright');
    log(`路径: ${existingReportByHash}`, 'green');
    log('提示: 当前暂存区内容已统计过，跳过重复统计', 'yellow');
    log('\n如需强制重新统计，请删除已有报告后重试', 'blue');
    // 跳过报告生成，也不更新 summary（因为是完全相同的暂存区内容）
    return;
  }

  // 生成报告
  const { reportPath, isUpdate } = generateReport(username, stats, commitInfo, process.cwd(), commitHash, taskName);

  // 更新 summary.md（累加新数据）
  updateHistoricalStats(username, process.cwd(), stats, isUpdate);

  log('\n📄 报告已生成', 'bright');
  log('================', 'bright');
  if (isUpdate) {
    log(`模式: 更新现有报告`, 'blue');
  } else {
    log(`模式: 新建报告`, 'green');
  }
  log(`路径: ${reportPath}`, 'green');
  log('\n提示: 报告已保存，请在 pre-commit 中自动添加或手动 git add', 'yellow');

  // 如果 AI 代码占比过高，给出警告
  if (parseFloat(aiPercent) > 70) {
    log('\n⚠️ 警告: AI 生成代码占比超过 70%，请确保代码质量', 'red');
  }
}

// 执行
main();
